INSERT INTO courses(slug,title_en,title_ar,description_ar,icon,template,ord,published) VALUES('accounting','Accounting','المحاسبة','من القيد المزدوج حتى المراجعة والتحليل المالي، مع المصطلحات الإنجليزية التي يحتاجها المحاسب.','🧮','accounting',1,1) ON CONFLICT (slug) DO NOTHING;
