INSERT INTO levels(course_id,ord,title_en,title_ar,description_ar) SELECT id,1,'Accounting Basics','أساسيات المحاسبة','القيد المزدوج، الأصول والخصوم وحقوق الملكية، دفتر اليومية.' FROM courses WHERE slug='accounting' ON CONFLICT (course_id,ord) DO NOTHING;
